// Mengembalikan probabilitas kelas 1 (0..1), sama dengan predict_proba(X)[:,1]
function rfPredict(name, x) {
  const trees = RF_MODELS[name];
  const xf = x.map(Math.fround);
  let s = 0;
  for (const [feat, thr, right, prob] of trees) {
    let i = 0;
    while (feat[i] >= 0) i = xf[feat[i]] <= thr[i] ? i + 1 : right[i];
    s += prob[i];
  }
  return s / trees.length;
}
  
